INSERT INTO sources (id, title, authors, year, journal, doi, url, source_type, accessed_date, notes) VALUES ('src-powo-hibiscus-sabdariffa', 'Hibiscus sabdariffa L.', 'Plants of the World Online, Royal Botanic Gardens, Kew', NULL, NULL, NULL, NULL, 'database', '2026-10-14', 'Name, authorship, family (Malvaceae) and native range verified on the POWO taxon page 2026-10-14. Note: POWO now treats Hibiscus sabdariffa as a synonym of Sabdariffa gossypiifolia following reinstatement of genus Sabdariffa (Hibiscus found polyphyletic); the medicinal literature uniformly uses Hibiscus sabdariffa, which is retained here. Exact taxon URL not preserved in working notes.');
