INSERT INTO sources (id, title, authors, year, journal, doi, url, source_type, accessed_date, notes) VALUES ('src-powo-piscidia-piscipula', 'Piscidia piscipula (L.) Sarg.', 'Plants of the World Online, Royal Botanic Gardens, Kew', NULL, NULL, NULL, NULL, 'database', '2026-10-14', 'Accepted name, authorship, family (Fabaceae) and native range verified on the POWO taxon page. Exact taxon URL not preserved in working notes; page fetched 2026-10-14.');
