INSERT INTO sources (id, title, authors, year, journal, doi, url, source_type, accessed_date, notes) VALUES ('src-powo-bryophyllum-pinnatum', 'Bryophyllum pinnatum (Lam.) Oken', 'Plants of the World Online, Royal Botanic Gardens, Kew', NULL, NULL, NULL, NULL, 'database', '2026-10-14', 'Name, authorship, family (Crassulaceae) and native/introduced range verified on the POWO taxon page 2026-10-14. Note: POWO accepts Kalanchoe pinnata (Lam.) Pers. with Bryophyllum pinnatum as a homotypic synonym; Caribbean/TRAMIL literature uses Bryophyllum pinnatum, which is retained here. Exact taxon URL not preserved in working notes.');
INSERT INTO sources (id, title, authors, year, journal, doi, url, source_type, accessed_date, notes) VALUES ('src-powo-passiflora-edulis', 'Passiflora edulis Sims', 'Plants of the World Online, Royal Botanic Gardens, Kew', NULL, NULL, NULL, NULL, 'database', '2026-10-14', 'Accepted name, authorship, family (Passifloraceae) and native/introduced range verified on the POWO taxon page. P. edulis chosen over P. incarnata (southeastern USA native only, no Caribbean distribution) and P. quadrangularis. Exact taxon URL not preserved in working notes; page fetched 2026-10-14.');
INSERT INTO sources (id, title, authors, year, journal, doi, url, source_type, accessed_date, notes) VALUES ('src-tramil-trinidad-2015', 'Medicinal plants used in Trinidad and Tobago: a TRAMIL-methodology ethnobotanical survey', 'Clement, Y.N. et al.', 2015, 'Journal of Ethnobiology and Ethnomedicine', '10.1186/s13002-015-0052-0', 'https://doi.org/10.1186/s13002-015-0052-0', 'ethnobotanical', '2026-10-14', 'TRAMIL-methodology survey of 450 households in Trinidad and Tobago. Documents: fevergrass/fever (46 cites), caraille/Momordica/diabetes (7), saffron-hardi/Curcuma/afterbirth (17), ginger/cold & cough (2), aloes/cooling (8), soursop/HBP (8), neem/diabetes (7), gully root/Petiveria/cold & cough (1), breadfruit/HBP (11), passion fruit/P. edulis/HBP (1), barbadine/P. quadrangularis/HBP (9). Guava, hibiscus, moringa, dogwood, Bryophyllum not in this survey.');
INSERT INTO sources (id, title, authors, year, journal, doi, url, source_type, accessed_date, notes) VALUES ('src-tramil-jamaica-2015', 'Traditional herbal medicine use in Jamaica: a TRAMIL ethnobotanical survey', 'Picking, D. et al.', 2015, 'Journal of Ethnopharmacology', '10.1016/j.jep.2015.04.027', 'https://doi.org/10.1016/j.jep.2015.04.027', 'ethnobotanical', '2026-10-14', 'TRAMIL survey of Jamaica (J Ethnopharmacol 169:314-327, PMID 25929450). Documents: cerasee/blood cleanse (67 cites), leaf of life/Bryophyllum/cold (51), sinkle bible/Aloe/washout (54), soursop/nerves (83), fever grass/fever (70, TRAMIL-significant), ginger/bellyache (25), guinea hen weed/headache (23).');
INSERT INTO sources (id, title, authors, year, journal, doi, url, source_type, accessed_date, notes) VALUES ('src-guava-liu-2024', 'Traditional uses of Psidium guajava for diarrheal disorders: a multi-country review', 'Liu et al.', 2024, 'Frontiers in Pharmacology', '10.3389/fphar.2024.1459066', 'https://doi.org/10.3389/fphar.2024.1459066', 'peer_reviewed', '2026-10-14', 'Review covering 44 countries including Trinidad and Tobago, Cuba, Guadeloupe and Martinique; documents guava leaf use for diarrhea. PMC11377350.');
INSERT INTO sources (id, title, authors, year, journal, doi, url, source_type, accessed_date, notes) VALUES ('src-guava-gutierrez-2008', 'Psidium guajava: a review of its traditional uses, phytochemistry and pharmacology', 'Gutiérrez, R.M.P.; Mitchell, S.; Solis, R.V.', 2008, 'Journal of Ethnopharmacology', NULL, NULL, 'peer_reviewed', '2026-10-14', 'J Ethnopharmacol 117(1):1-27, PMID 18353572. Backup source for guava traditional uses. URL not preserved in working notes.');
INSERT INTO sources (id, title, authors, year, journal, doi, url, source_type, accessed_date, notes) VALUES ('src-hibiscus-toptropicals', 'Hibiscus sabdariffa (Roselle) plant profile', 'TopTropicals', NULL, NULL, NULL, 'https://toptropicals.com/catalog/uid/hibiscus_sabdariffa.htm', 'community', '2026-10-14', 'Documents the sorrel Christmas drink tradition in Jamaica and folk antihypertensive use; confirms ''sorrel'' as the Jamaican name.');
INSERT INTO sources (id, title, authors, year, journal, doi, url, source_type, accessed_date, notes) VALUES ('src-moringa-mdpi-2017', 'Moringa oleifera in Jamaica: nutritional and medicinal review', NULL, 2017, 'Plants (MDPI)', NULL, 'https://www.mdpi.com/2223-7747/6/4/48', 'peer_reviewed', '2026-10-14', 'Documents moringa teas, juices and meals in Jamaican households since the 2000s.');
INSERT INTO sources (id, title, authors, year, journal, doi, url, source_type, accessed_date, notes) VALUES ('src-petiveria-costarica-2006', 'Petiveria alliacea: TRAMIL study on traditional uses and safety (Costa Rica)', NULL, 2006, 'Revista de Biología Tropical', NULL, 'https://www.scielo.sa.cr/scielo.php?script=sci_arttext&pid=S0034-77442006000500017', 'ethnobotanical', '2026-10-14', 'Costa Rican TRAMIL study documenting an abortive effect attributed to Petiveria (uterine smooth-muscle contraction); contraindicated in pregnancy. Corroborated for Jamaica.');
INSERT INTO sources (id, title, authors, year, journal, doi, url, source_type, accessed_date, notes) VALUES ('src-cerasee-zhang-2024', 'Momordica charantia for glycemic control: systematic review and meta-analysis of randomized controlled trials', 'Zhang et al.', 2024, 'Heliyon', '10.1016/j.heliyon.2024.e31126', 'https://doi.org/10.1016/j.heliyon.2024.e31126', 'systematic_review', '2026-10-14', '8 RCTs, n=423. FBG -0.85 mmol/L, PPG -2.28 mmol/L, HbA1c -0.38%, total cholesterol -0.38 mmol/L. High heterogeneity; findings conflict with Cochrane review (insufficient evidence) and one 2024 null review. PMID 38784554, PMC11112315.');
INSERT INTO sources (id, title, authors, year, journal, doi, url, source_type, accessed_date, notes) VALUES ('src-ginger-viljoen-2014', 'A systematic review and meta-analysis of ginger for nausea and vomiting', 'Viljoen, E. et al.', 2014, 'Nutrition Journal', NULL, 'https://doi.org/10.1186/1475-2891-13-20', 'systematic_review', '2026-10-14', 'Nutr J 13:20. 12 RCTs, n=1278. Nausea improved; vomiting not significantly reduced. Low-quality evidence overall; no significant safety signal. PMID 24642205, PMC3995184.');
INSERT INTO sources (id, title, authors, year, journal, doi, url, source_type, accessed_date, notes) VALUES ('src-hibiscus-ellis-2022', 'Hibiscus sabdariffa for blood pressure: systematic review and meta-analysis', 'Ellis et al.', 2022, 'Nutrition Reviews', NULL, 'https://doi.org/10.1093/nutrit/nuab104', 'systematic_review', '2026-10-14', 'Nutr Rev 80(6):1723-1737. 17 RCTs; systolic BP -7.10 mmHg vs placebo. PMID 34927694, PMC9086798.');
INSERT INTO sources (id, title, authors, year, journal, doi, url, source_type, accessed_date, notes) VALUES ('src-turmeric-daily-2016', 'Efficacy of turmeric extracts and curcumin for alleviating arthritis symptoms: systematic review and meta-analysis', 'Daily, J.W.; Yang, M.; Park, S.', 2016, 'Journal of Medicinal Food', NULL, 'https://doi.org/10.1089/jmf.2016.3705', 'systematic_review', '2026-10-14', 'J Med Food 19(8):717-729. 8 RCTs; pain VAS -2.04, WOMAC -15.36. DISCLOSURE: first author affiliated with Daily Manufacturing, Inc. (turmeric supplement manufacturer). PMID 27533649, PMC5003001.');
INSERT INTO sources (id, title, authors, year, journal, doi, url, source_type, accessed_date, notes) VALUES ('src-aloe-hekmatpou-2019', 'Aloe vera for wound healing: review of clinical trials', 'Hekmatpou, D. et al.', 2019, 'Iranian Journal of Medical Sciences', NULL, NULL, 'systematic_review', '2026-10-14', '23 clinical trials reviewed; supports complementary use of Aloe vera for burn wound healing. PMC6330525, PMID 30666070. URL not preserved in working notes.');
INSERT INTO sources (id, title, authors, year, journal, doi, url, source_type, accessed_date, notes) VALUES ('src-soursop-moghadamtousi-2015', 'Annona muricata (soursop): phytochemistry and anticancer potential', 'Moghadamtousi, S.Z. et al.', 2015, 'International Journal of Molecular Sciences', '10.3390/ijms160715625', 'https://doi.org/10.3390/ijms160715625', 'peer_reviewed', '2026-10-14', 'Int J Mol Sci 16(7):15625-15658. Anticancer evidence limited to in vitro and animal studies; no human trials.');
INSERT INTO sources (id, title, authors, year, journal, doi, url, source_type, accessed_date, notes) VALUES ('src-soursop-lannuzel-2003', 'Annonacin neurotoxicity and atypical parkinsonism', 'Lannuzel, A. et al.', 2003, 'Journal of Neurochemistry', NULL, NULL, 'peer_reviewed', '2026-10-14', 'PMID 14675150. Annonacin (from Annonaceae, incl. soursop) is neurotoxic; linked to atypical parkinsonism in Guadeloupe. URL not preserved in working notes.');
INSERT INTO sources (id, title, authors, year, journal, doi, url, source_type, accessed_date, notes) VALUES ('src-petiveria-hernandez-2017', 'Petiveria alliacea in a mouse breast-cancer model', 'Hernandez et al.', 2017, NULL, NULL, 'https://link.springer.com/article/10.1186/s12906-023-04109-2', 'peer_reviewed', '2026-10-14', 'Mouse breast-cancer model study of Petiveria alliacea (accessed via BMC protocol page). Preliminary animal evidence only.');
INSERT INTO sources (id, title, authors, year, journal, doi, url, source_type, accessed_date, notes) VALUES ('src-breadfruit-nwokocha-2012', 'Hypotensive and bradycardic effects of Artocarpus altilis leaf extract in rats', 'Nwokocha, C.R. et al.', 2012, 'Pharmaceutical Biology', NULL, NULL, 'peer_reviewed', '2026-10-14', 'PMID 22830437. Aqueous breadfruit leaf extract hypotensive and bradycardic in rats (UWI Mona, Jamaica). Animal evidence only. URL not preserved in working notes.');
INSERT INTO sources (id, title, authors, year, journal, doi, url, source_type, accessed_date, notes) VALUES ('src-moringa-stohs-2015', 'Moringa oleifera: review of safety and efficacy in human studies', 'Stohs, S.J.; Hartman, M.J.', 2015, 'Phytotherapy Research', NULL, NULL, 'systematic_review', '2026-10-14', 'PMID 25808883, PMC6680322. 5 human studies; anti-hyperglycemic and anti-dyslipidemic effects; no adverse effects reported. Small studies. URL not preserved in working notes.');
INSERT INTO sources (id, title, authors, year, journal, doi, url, source_type, accessed_date, notes) VALUES ('src-kalanchoe-mdpi-review', 'Kalanchoe pinnata (Bryophyllum pinnatum): phytochemistry and pharmacology review', NULL, NULL, 'Molecules (MDPI)', NULL, 'https://www.mdpi.com/1420-3049/31/19/3456', 'peer_reviewed', '2026-10-14', 'Review; preclinical wound-healing evidence is the most extensive. Also documents bufadienolides (cardiac-glycoside poisoning risk).');
INSERT INTO sources (id, title, authors, year, journal, doi, url, source_type, accessed_date, notes) VALUES ('src-dogwood-webmd', 'Jamaican Dogwood: uses, side effects and safety', 'WebMD', NULL, NULL, NULL, 'https://www.webmd.com/vitamins/ai/ingredientmono-682/jamaican-dogwood', 'institutional', '2026-10-14', 'States there is no evidence supporting Jamaican dogwood use or any other use in humans (evidence gap explicitly discussed). Documents rotenone-related toxicity risks.');
INSERT INTO sources (id, title, authors, year, journal, doi, url, source_type, accessed_date, notes) VALUES ('src-neem-oil-toxicity', 'Neem oil poisoning: clinical review', NULL, NULL, NULL, NULL, 'https://www.ncbi.nlm.nih.gov/pmc/articles/PMC9358515/', 'peer_reviewed', '2026-10-14', 'PMC9358515. Review of neem oil poisoning, esp. pediatric: hepatic toxicity, encephalopathy, seizures.');
INSERT INTO sources (id, title, authors, year, journal, doi, url, source_type, accessed_date, notes) VALUES ('src-passiflora-scielo-2015', 'Anxiolytic and antidepressant-like effects of Passiflora edulis leaf extract in mice', NULL, 2015, 'Revista Brasileira de Farmacognosia (SciELO)', NULL, 'https://www.scielo.br/j/rbfar/a/Ms6phR8kXHd9wqV3qpZtNbG/', 'peer_reviewed', '2026-10-14', 'Aqueous Passiflora edulis leaf extract showed anxiolytic and antidepressant-like effects in mice; notes traditional Brazilian use for anxiety and insomnia. Animal evidence only.');
INSERT INTO sources (id, title, authors, year, journal, doi, url, source_type, accessed_date, notes) VALUES ('src-nccih-aloe', 'Aloe vera: NCCIH herbs at a glance', 'National Center for Complementary and Integrative Health', NULL, NULL, NULL, 'https://www.nccih.nih.gov/health/aloe-vera', 'institutional', '2026-10-14', 'NCCIH summary: some support for burn/wound healing; aloe latex risks; IARC classifies aloe vera leaf extract as possibly carcinogenic to humans; pregnancy caution.');
INSERT INTO sources (id, title, authors, year, journal, doi, url, source_type, accessed_date, notes) VALUES ('src-turmeric-safety-nhs', 'Turmeric: adverse effects information', 'Welsh NHS / NHS Wales', NULL, NULL, NULL, NULL, 'institutional', '2026-10-14', 'Documents turmeric adverse effects: gallstone/biliary concerns, liver injury reports, bleeding risk. URL not preserved in working notes.');
INSERT INTO sources (id, title, authors, year, journal, doi, url, source_type, accessed_date, notes) VALUES ('src-img-fever-grass-starr', 'Wikimedia Commons file: Cymbopogon citratus (fever grass) photograph', 'Forest and Kim Starr', 2015, NULL, NULL, 'https://commons.wikimedia.org/wiki/File:Starr-150325-0455-Cymbopogon_citratus-in_planter_with_float_mulch-Residences_Sand_Island-Midway_Atoll_(25265744835).jpg', 'community', '2026-10-14', 'File page opened and license verified in page text: CC BY 3.0 US (https://creativecommons.org/licenses/by/3.0/us/deed.en). Author: Forest and Kim Starr.');
INSERT INTO sources (id, title, authors, year, journal, doi, url, source_type, accessed_date, notes) VALUES ('src-img-neem-azogbonon', 'Wikimedia Commons file: Margousier ou Neem 01 (Azadirachta indica)', 'Azogbonon', NULL, NULL, NULL, 'https://commons.wikimedia.org/wiki/File:Margousier_ou_Neem_01.jpg', 'community', '2026-10-14', 'File page opened and license verified in page text: CC0 1.0 Universal Public Domain Dedication.');
INSERT INTO sources (id, title, authors, year, journal, doi, url, source_type, accessed_date, notes) VALUES ('src-img-wonder-starr', 'Wikimedia Commons file: Kalanchoe pinnata (syn. Bryophyllum pinnatum) photograph', 'Forest and Kim Starr', 2015, NULL, NULL, 'https://commons.wikimedia.org/wiki/File:Starr-150326-0110-Kalanchoe_pinnata-in_pot-Comodore_Ave_Residences_Sand_Island-Midway_Atoll_(24635834884).jpg', 'community', '2026-10-14', 'File page opened and license verified in page text: CC BY 3.0 US. File description notes ''Also known as Bryophyllum pinnatum''.');
