INSERT INTO sources (id, title, authors, year, journal, doi, url, source_type, accessed_date, notes) VALUES ('src-img-hibiscus-roselle', 'Wikimedia Commons file: Roselle (Hibiscus sabdariffa) flowers', 'Ikiwaner', 2008, NULL, NULL, 'https://commons.wikimedia.org/wiki/File:Roselle.jpg', 'community', '2026-10-14', 'File page opened and license verified in page text: dual GFDL 1.2+ and CC BY-SA 3.0 Unported (http://creativecommons.org/licenses/by-sa/3.0/). Self-photographed 27 Feb 2008, Serekunda market, The Gambia; depicts Hibiscus sabdariffa.');
INSERT INTO sources (id, title, authors, year, journal, doi, url, source_type, accessed_date, notes) VALUES ('src-img-ginger-seikei', 'Wikimedia Commons file: Seikei Zusetsu ginger plate (Zingiber officinale, 1804)', 'Anonymous (Leiden University Library collection)', 1804, NULL, NULL, 'https://commons.wikimedia.org/wiki/File:Leiden_University_Library_-_Seikei_Zusetsu_vol._24,_page_036_-_%E7%94%9F%E5%A7%9C_-_Zingiber_officinale_Roscoe,_1804.jpg', 'historical', '2026-10-14', 'File page opened and license verified in page text: CC BY 4.0 International. 1804 Japanese botanical illustration; description confirms species Zingiber officinale Roscoe. Used on Dutch and Japanese Wikipedia.');
INSERT INTO sources (id, title, authors, year, journal, doi, url, source_type, accessed_date, notes) VALUES ('src-img-soursop-blanco', 'Wikimedia Commons file: Annona muricata (Blanco, Flora de Filipinas)', 'Francisco Manuel Blanco (O.S.A.)', 1883, NULL, NULL, 'https://commons.wikimedia.org/wiki/File:Annona_muricata_Blanco1.196.png', 'historical', '2026-10-14', 'File page opened: plate from Flora de Filipinas, dated 1880-1883, author Francisco Manuel Blanco (d. 1845). Public domain by age of publication (pre-1929 publication). The license badge did not render in text extraction; PD status determined from the publication date and author shown on the file page. Used on English Wikipedia Soursop article.');
INSERT INTO plants (id, slug, common_name, scientific_name, scientific_name_authorship, family, botanical_description, identification, parts_used, constituents, cultural_background, traditional_use_summary, disambiguation_note, safety_summary, side_effects, interactions, pregnancy, children, contraindications, reviewer_status, featured, last_reviewed, created_at) VALUES ('fever-grass', 'fever-grass', 'Fever Grass', 'Cymbopogon citratus', '(DC.) Stapf', 'Poaceae', NULL, NULL, '["Leaves"]', '[]', NULL, 'Leaf tea widely used across the Caribbean to bring down fever; one of the most-cited remedies in Jamaican and Trinidadian ethnobotanical surveys.', 'Fever grass here is Cymbopogon citratus (lemongrass). It is distinct from citronella grasses (Cymbopogon nardus / C. winterianus), which are grown mainly for mosquito-repelling oil and are not the traditional fever remedy.', NULL, NULL, NULL, NULL, NULL, NULL, 'verified', 1, '2026-10-14', '2026-10-15T00:40:10.501Z');
