INSERT INTO evidence_assessments (id, claim_id, category, summary, study_design, population, preparation_studied, main_findings, limitations, adverse_effects, reviewer_status, last_reviewed) VALUES (2, 2, 'moderate_human', 'A 2024 meta-analysis of 8 RCTs (n=423) found bitter melon reduced fasting blood glucose (-0.85 mmol/L), postprandial glucose (-2.28 mmol/L) and HbA1c (-0.38%), but heterogeneity was high and findings conflict with the Cochrane review and a 2024 null review.', 'Systematic review and meta-analysis of randomized controlled trials', '423 adults with diabetes/prediabetes across 8 RCTs', 'Momordica charantia preparations (various)', 'FBG -0.85 mmol/L; PPG -2.28 mmol/L; HbA1c -0.38%; total cholesterol -0.38 mmol/L.', 'High heterogeneity; small trials; conflicts with Cochrane (insufficient evidence) and one 2024 null review.', NULL, 'verified', '2026-10-14');
