INSERT INTO plants (id, slug, common_name, scientific_name, scientific_name_authorship, family, botanical_description, identification, parts_used, constituents, cultural_background, traditional_use_summary, disambiguation_note, safety_summary, side_effects, interactions, pregnancy, children, contraindications, reviewer_status, featured, last_reviewed, created_at) VALUES ('turmeric', 'turmeric', 'Turmeric', 'Curcuma longa', 'L.', 'Zingiberaceae', NULL, NULL, '["Rhizome"]', '[]', NULL, 'Known as saffron/hardi in Trinidad and Tobago, where it is used for afterbirth care; turmeric is also the subject of modern arthritis research.', 'Turmeric is Curcuma longa. In Trinidad it is called ''saffron'' (saffron-hardi), not to be confused with true saffron (Crocus sativus).', 'Welsh NHS information documents turmeric adverse effects including gallstone/biliary concerns, reported liver injury, and bleeding risk.', 'Gallbladder/biliary effects; liver injury has been reported.', 'Bleeding risk (caution with anticoagulants).', NULL, NULL, 'Caution with gallstones/biliary obstruction.', 'draft', 0, '2026-10-14', '2026-10-15T00:40:10.501Z');
